import{_ as p,a0 as l,w as r,s as o,ao as d,I as t,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"用 ranger 在 Linux 文件的海洋中导航 | LCTT x X-CMD","titleTemplate":false,"description":"用 ranger 在 Linux 文件的海洋中导航 | LCTT (202102) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 ranger 在 Linux 文件的海洋中导航 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 ranger 在 Linux 文件的海洋中导航 | LCTT (202102) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202102/20201001 Navigating your Linux files with ranger","title":"用 ranger 在 Linux 文件的海洋中导航","tag":"202102","desc":""},"relativePath":"202102/20201001 Navigating your Linux files with ranger.md","filePath":"[post].md"}'),c={name:"202102/20201001 Navigating your Linux files with ranger.md"};function g(h,s,u,k,f,b){const a=l("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="用-ranger-在-linux-文件的海洋中导航" tabindex="-1">用 ranger 在 Linux 文件的海洋中导航 <a class="header-anchor" href="#用-ranger-在-linux-文件的海洋中导航" aria-label="Permalink to “用 ranger 在 Linux 文件的海洋中导航”">​</a></h1><blockquote><p>ranger 是一个很好的工具，它为你的 Linux 文件提供了一个多级视图，并允许你使用方向键和一些方便的命令进行浏览和更改。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202102/20/121918g5hqhjfcjyffh3lt.jpg" alt=""></p><p><code>ranger</code> 是一款独特且非常方便的文件系统导航器，它允许你在 Linux 文件系统中移动，进出子目录，查看文本文件内容，甚至可以在不离开该工具的情况下对文件进行修改。</p><p>它运行在终端窗口中，并允许你按下方向键进行导航。它提供了一个多级的文件显示，让你很容易看到你在哪里、在文件系统中移动、并选择特定的文件。</p><p>要安装 <code>ranger</code>，请使用标准的安装命令（例如，<code>sudo apt install ranger</code>）。要启动它，只需键入 <code>ranger</code>。它有一个很长的、非常详细的手册页面，但开始使用 <code>ranger</code> 非常简单。</p><h3 id="ranger-的显示方式" tabindex="-1">ranger 的显示方式 <a class="header-anchor" href="#ranger-的显示方式" aria-label="Permalink to “ranger 的显示方式”">​</a></h3><p>你需要马上习惯的最重要的一件事就是 <code>ranger</code> 的文件显示方式。一旦你启动了 <code>ranger</code>，你会看到四列数据。第一列是你启动 <code>ranger</code> 的位置的上一级。例如，如果你从主目录开始，<code>ranger</code> 将在第一列中列出所有的主目录。第二列将显示你的主目录（或者你开始的目录）中的目录和文件的第一屏内容。</p><p>这里的关键是超越你可能有的任何习惯，将每一行显示的细节看作是相关的。第二列中的所有条目与第一列中的单个条目相关，第四列中的内容与第二列中选定的文件或目录相关。</p><p>与一般的命令行视图不同的是，目录将被列在第一位（按字母数字顺序），文件将被列在第二位（也是按字母数字顺序）。从你的主目录开始，显示的内容可能是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shs@dragonfly /home/shs/backups     &lt;== current selection</span></span>
<span class="line"><span> bugfarm   backups            0  empty</span></span>
<span class="line"><span> dory      bin               59</span></span>
<span class="line"><span> eel       Buttons           15</span></span>
<span class="line"><span> nemo      Desktop            0</span></span>
<span class="line"><span> shark     Documents          0</span></span>
<span class="line"><span> shs       Downloads          1</span></span>
<span class="line"><span>   ^         ^                ^      ^</span></span>
<span class="line"><span>   |         |                |      |</span></span>
<span class="line"><span> homes     directories    # files    listing</span></span>
<span class="line"><span>           in selected    in each    of files in</span></span>
<span class="line"><span>           home           directory  selected directory</span></span></code></pre></div><p><code>ranger</code> 显示的最上面一行告诉你在哪里。在这个例子中，当前目录是 <code>/home/shs/backups</code>。我们看到高亮显示的是 <code>empty</code>，因为这个目录中没有文件。如果我们按下方向键选择 <code>bin</code>，我们会看到一个文件列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shs@dragonfly /home/shs/bin      &lt;== current selection</span></span>
<span class="line"><span> bugfarm   backups            0    append</span></span>
<span class="line"><span> dory      bin               59    calcPower</span></span>
<span class="line"><span> eel       Buttons           15    cap</span></span>
<span class="line"><span> nemo      Desktop            0    extract</span></span>
<span class="line"><span> shark     Documents          0    finddups</span></span>
<span class="line"><span> shs       Downloads          1    fix</span></span>
<span class="line"><span>   ^         ^                ^      ^</span></span>
<span class="line"><span>   |         |                |      |</span></span>
<span class="line"><span> homes     directories    # files    listing</span></span>
<span class="line"><span>           in selected    in each    of files in</span></span>
<span class="line"><span>           home           directory  selected directory</span></span></code></pre></div><p>每一列中高亮显示的条目显示了当前的选择。使用右方向键可移动到更深的目录或查看文件内容。</p><p>如果你继续按下方向键移动到列表的文件部分，你会注意到第三列将显示文件大小（而不是文件的数量）。“当前选择”行也会显示当前选择的文件名，而最右边的一列则会尽可能地显示文件内容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>shs@dragonfly /home/shs/busy_wait.c   &lt;== current selection</span></span>
<span class="line"><span> bugfarm   BushyRidge.zip    170 K  /*</span></span>
<span class="line"><span> dory      busy_wait.c       338 B   * program that does a busy wait</span></span>
<span class="line"><span> eel       camper.jpg       5.55 M   * it&#39;s used to show ASLR, and that&#39;s it</span></span>
<span class="line"><span> nemo      check_lockscreen   80 B   */</span></span>
<span class="line"><span> shark     chkrootkit-output 438 B  #include &lt;stdio.h&gt;</span></span>
<span class="line"><span>   ^         ^                ^       ^</span></span>
<span class="line"><span>   |         |                |       |</span></span>
<span class="line"><span> homes     files            sizes    file content</span></span></code></pre></div><p>在该显示的底行会显示一些文件和目录的详细信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-rw-rw-r—- shs shs 338B 2019-01-05 14:44    1.52G, 365G free  67/488  11%</span></span></code></pre></div><p>如果你选择了一个目录并按下回车键，你将进入该目录。然后，在你的显示屏中最左边的一列将是你的主目录的内容列表，第二列将是该目录内容的文件列表。然后你可以检查子目录的内容和文件的内容。</p><p>按左方向键可以向上移动一级。</p><p>按 <code>q</code> 键退出 <code>ranger</code>。</p><h3 id="做出改变" tabindex="-1">做出改变 <a class="header-anchor" href="#做出改变" aria-label="Permalink to “做出改变”">​</a></h3><p>你可以按 <code>?</code> 键，在屏幕底部弹出一条帮助行。它看起来应该是这样的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>View [m]an page, [k]ey bindings, [c]commands or [s]ettings?  (press q to abort)</span></span></code></pre></div><p>按 <code>c</code> 键，<code>ranger</code> 将提供你可以在该工具内使用的命令信息。例如，你可以通过输入 <code>:chmod</code> 来改变当前文件的权限，后面跟着预期的权限。例如，一旦选择了一个文件，你可以输入 <code>:chmod 700</code> 将权限设置为 <code>rwx------</code>。</p><p>输入 <code>:edit</code> 可以在 <code>nano</code> 中打开该文件，允许你进行修改，然后使用 <code>nano</code> 的命令保存文件。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>使用 <code>ranger</code> 的方法比本篇文章所描述的更多。该工具提供了一种非常不同的方式来列出 Linux 系统上的文件并与之交互，一旦你习惯了它的多级的目录和文件列表方式，并使用方向键代替 <code>cd</code> 命令来移动，就可以很轻松地在 Linux 的文件中导航。</p><hr>`,29)),t("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://www.networkworld.com/article/3583890/navigating-your-linux-files-with-ranger.html"},{default:i(()=>[...s[0]||(s[0]=[n("https://www.networkworld.com/article/3583890/navigating-your-linux-files-with-ranger.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=n("作者：",-1)),e(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=n(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 译者：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1}),s[9]||(s[9]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[n("Linux中国",-1)])]),_:1}),s[14]||(s[14]=n(" 荣誉推出",-1))])])}const w=p(c,[["render",g]]);export{y as __pageData,w as default};
